local Players = game:GetService("Players")
local MarketplaceService = game:WaitForChild("MarketplaceService")
local DataStoreService = game:GetService("DataStoreService")
local purchasesStore = DataStoreService:GetDataStore("Robux_PurchaseOrders")
local handleStore = DataStoreService:GetDataStore("Robux_HandledReceipts")
local errorStore = DataStoreService:GetDataStore("Robux_ErrorReceipts")
local WuKongRobloxProductHelper = require(game.ReplicatedStorage.Packages.WuKong.WuKongRobloxProductHelper)
local purchasedEvent = game.ReplicatedStorage.Packages.WuKong.PurchasedEvent
local module = {}

-- #region 购买记录处理
local function recordPurchase(playerId, receiptInfo, handled, isError)
	local ds = purchasesStore
	if handled then
		ds = handleStore
	end
	if isError then
		ds = errorStore
	end
	local info = {
		productId = receiptInfo.ProductId,
		currencySpent = receiptInfo.CurrencySpent,
		purchaseId = receiptInfo.PurchaseId,
		created = os.time(),
		type = receiptInfo.Type,
	}
	spawn(function()
		local suc = pcall(function()
			ds:UpdateAsync(playerId, function(orders)
				if not orders then
					orders = {}
				end
				-- 检查是否已经存在
				for i, v in ipairs(orders) do
					if v.purchaseId == receiptInfo.PurchaseId then
						return orders
					end
				end
				-- 插入到第一位
				table.insert(orders, 1, info)
				return orders
			end)
		end)
		if not suc then
			warn("Failed to record purchase for player " .. playerId)
		end
	end)
end
-- #endregion

-- #region 订单回调

function module.onProcessReceipt(receiptInfo)
	local playerId = receiptInfo.PlayerId
	local player = Players:GetPlayerByUserId(playerId)

	-- 玩家不在本服务器
	if not player then
		return Enum.ProductPurchaseDecision.NotProcessedYet
	end

	local productId = receiptInfo.ProductId

	-- 记录付款单
	recordPurchase(playerId, receiptInfo, false)

	local wukongServer = require(script.Parent)
	local facade = wukongServer.WaitFacade(playerId)

	-- 玩家中途退出了
	if not facade then
		return Enum.ProductPurchaseDecision.NotProcessedYet
	end

	-- 悟空 发商品
	local suc1, productPath = pcall(function()
		return WuKongRobloxProductHelper.GetVendorPathByRobloxId(facade:GetContainer(), productId)
	end)
	local suc, res = pcall(function()
		local price = facade:ExecuteQuery(productPath .. "?获取R币价格")
		return facade:ExecuteAction(productPath .. "?为R币消费发货", price)
	end)

	-- 购买成功， 入库
	if suc then
		recordPurchase(playerId, receiptInfo, true)
	else
		recordPurchase(playerId, receiptInfo, true, true)
	end

	-- 发送客户端事件
	if player then
		local send = pcall(function()
			purchasedEvent:FireClient(player, "PurchaseResult", productId, productPath, suc, res)
		end)
		if not send then
			purchasedEvent:FireClient(player, "PurchaseResult", productId, productPath, suc)
		end
	end

	-- 返回订单已处理
	return Enum.ProductPurchaseDecision.PurchaseGranted
end

-- pass 通知仅执行一次
-- 无论悟空发货与否,  不再调用
-- 所以需要在用户登录后,再次检查pass情况
-- 同时, pass也不应该有发货记录(不准确,就不再记录)
MarketplaceService.PromptGamePassPurchaseFinished:Connect(function(player, gamePassId, purchased)
	if purchased and player and player.Parent == game.Players then
		local productId = gamePassId
		local playerId = player.UserId

		local receiptInfo = {
			ProductId = gamePassId,
			created = os.time(),
			Type = "Pass",
		}

		local wukongServer = require(script.Parent)
		local facade = wukongServer.WaitFacade(playerId)

		-- 悟空 发商品
		local suc1, productPath = pcall(function()
			return WuKongRobloxProductHelper.GetVendorPathByRobloxId(facade:GetContainer(), productId)
		end)

		local suc, res = pcall(function()
			local price = facade:ExecuteQuery(productPath .. "?获取R币价格")
			receiptInfo.currencySpent = price
			return facade:ExecuteAction(productPath .. "?为R币消费发货", price)
		end)

		-- 发送客户端事件

		if player then
			local send = pcall(function()
				purchasedEvent:FireClient(player, "PurchaseResult", productId, productPath, suc, res)
			end)
			if not send then
				purchasedEvent:FireClient(player, "PurchaseResult", productId, productPath, suc)
			end
		end

		-- 购买成功
		-- Pass不需要入发货库.
	end
end)

return module
